  let exhausted = 0

  for (const ballot of ballots) {
    const choice = ballot.preferences.find((name) => continuing.has(name))
    if (choice === undefined) {
      exhausted += ballot.count
    } else {
      counts.set(choice, counts.get(choice) + ballot.count)
    }
