  let survivors = tied
  for (const roundCounts of history) {
    if (survivors.length === 1) break
    const values = survivors.map((name) => roundCounts.get(name))
    const allEqual = values.every((v) => v === values[0])
    if (allEqual) continue
    const min = Math.min(...values)
    survivors = survivors.filter((name) => roundCounts.get(name) === min)
  }
