/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'node:fs'
import { parseElection, ParseError } from './parser.js'
import { runElection } from './election.js'
import { formatRound, formatOutcome } from './format.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  const mode = args[0]
  if (args.length !== 1 || (mode !== 'rounds' && mode !== 'tally')) {
    fail('usage: cli.js rounds|tally')
  }

  const input = readFileSync(0, 'utf8')

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ParseError) {
      fail(err.line === null ? err.message : `line ${err.line}: ${err.message}`)
    }
    throw err
  }

  const { rounds, winner } = runElection(election.candidates, election.ballots)

  const lines = []
  if (mode === 'rounds') {
    rounds.forEach((round, index) => {
      lines.push(formatRound(index + 1, round.counts, round.exhausted))
      if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
    })
  } else {
    lines.push(`rounds ${rounds.length}`)
  }
  lines.push(formatOutcome(winner))

  process.stdout.write(lines.join('\n') + '\n')
}

main()
"}

